// Post copy: caption + detailed description + short-form caption for a finished video.
// Written to out/post.txt (human) and out/post.json (machine) — generated by Claude from the
// script and the research notes; a plain template when no ANTHROPIC_API_KEY is set.
import fs from "node:fs";
import path from "node:path";
import type { Script } from "../src/schema";
import { log } from "./lib";

export type PostCopy = {
  title: string;
  facebook: string; // caption for the Facebook Reel / post
  description: string; // long description (Facebook "more", YouTube Shorts description)
  short: string; // TikTok / Shorts caption
  hashtags: string[];
  commentPrompt: string; // the question that drives comments
  sources: string[];
};

const claudeJson = async (system: string, user: string): Promise<Record<string, unknown> | null> => {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return null;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model: process.env.UTD_DRAFT_MODEL ?? "claude-sonnet-5-5", max_tokens: 1800, system, messages: [{ role: "user", content: user }] }),
  });
  if (!res.ok) {
    log(`post copy: Claude ${res.status} — using the template`);
    return null;
  }
  const json = (await res.json()) as { content: { type: string; text?: string }[] };
  const text = json.content.filter((b) => b.type === "text").map((b) => b.text ?? "").join("");
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]) as Record<string, unknown>;
  } catch {
    return null;
  }
};

const sourcesOf = (script: Script, research: string): string[] => {
  const out = new Set<string>();
  for (const sc of script.scenes) if ("source" in sc && sc.source) out.add(sc.source);
  for (const m of research.matchAll(/\((https?:\/\/[^\s)]+)\)|https?:\/\/[^\s|)]+/g)) out.add(m[1] ?? m[0]);
  return [...out].slice(0, 12);
};

const template = (script: Script, research: string): PostCopy => {
  const hook = script.scenes.find((s) => s.type === "hook");
  const word = hook && hook.type === "hook" ? hook.word : script.title;
  const sub = hook && hook.type === "hook" ? hook.sub ?? "" : "";
  const lines = script.scenes.map((s) => s.vo ?? "").filter(Boolean);
  const hashtags = ["#MUFC", "#ManchesterUnited", "#ManUtd", "#PremierLeague", "#UTDDiaries", "#Football", "#Tactics"];
  const sources = sourcesOf(script, research);
  return {
    title: script.title,
    facebook: `${word}\n\n${sub}\n\n${lines.slice(1, 3).join(" ")}\n\nWhat would you change? 👇\n\nFollow UTD Diaries for the full breakdowns.\n\n${hashtags.join(" ")}`,
    description: `${script.title}\n\n${lines.join("\n\n")}\n\nSources:\n${sources.map((s) => `• ${s}`).join("\n")}\n\n${hashtags.join(" ")}`,
    short: `${word} ${sub}`.trim().slice(0, 140) + " " + hashtags.slice(0, 4).join(" "),
    hashtags,
    commentPrompt: "What would you change?",
    sources,
  };
};

export const generatePost = async (dir: string, script: Script, durationSec?: number): Promise<PostCopy> => {
  const researchPath = path.join(dir, "research.md");
  const research = fs.existsSync(researchPath) ? fs.readFileSync(researchPath, "utf8") : "";
  const sources = sourcesOf(script, research);
  let post: PostCopy | null = null;

  const out = await claudeJson(
    `You write the post copy for "UTD Diaries", a Manchester United analysis page (Facebook Reels, TikTok, YouTube Shorts). Reply with JSON only:
{"title": string, "facebook": string, "description": string, "short": string, "hashtags": string[], "commentPrompt": string}
Rules:
- facebook (the Reel caption): line 1 is the hook — a curiosity line, not a summary (same spirit as the video's hook word); then 2–4 short lines with the sharpest facts; then ONE question that invites disagreement in the comments; then "Follow UTD Diaries for the full breakdowns."; then the hashtags on the last line. 500–900 characters. Short lines, blank lines between blocks. No "in this video". At most two emojis total.
- description (detailed, for the expanded post / Shorts description): 3–5 paragraphs that make the argument of the video in prose, every number and quote exactly as in the script with its source in brackets after it; a final "Sources:" list (one per line, outlet · date, URL if known). 1200–2000 characters. Facts only from the script and the research notes — never add new claims.
- short (TikTok/Shorts caption): ≤ 150 characters including 3–4 hashtags.
- hashtags: 6–9, mix #MUFC #ManchesterUnited #ManUtd #PremierLeague with 2–3 topic tags and #UTDDiaries.
- commentPrompt: the single question from the caption.
- Engagement comes from comments and reactions; never ask people to share.`,
    `Title: ${script.title}${script.series ? ` (${script.series})` : ""}${durationSec ? ` · ${Math.round(durationSec)}s` : ""}
Script voice-over, scene by scene:
${script.scenes.map((s, i) => `${i + 1}. [${s.type}] ${s.vo ?? ""}${"source" in s && s.source ? `  (source: ${s.source})` : ""}`).join("\n")}

Research notes:
${research.slice(0, 6000) || "(none)"}`,
  );
  if (out && typeof out.facebook === "string" && typeof out.description === "string") {
    post = {
      title: String(out.title ?? script.title),
      facebook: out.facebook,
      description: out.description,
      short: String(out.short ?? ""),
      hashtags: Array.isArray(out.hashtags) ? (out.hashtags as string[]).map(String) : [],
      commentPrompt: String(out.commentPrompt ?? ""),
      sources,
    };
  }
  if (!post) post = template(script, research);

  const txt = `${post.title}
${"=".repeat(Math.min(72, post.title.length))}

FACEBOOK CAPTION
----------------
${post.facebook.trim()}

DESCRIPTION (detailed)
----------------------
${post.description.trim()}

TIKTOK / SHORTS
---------------
${post.short.trim()}

HASHTAGS
--------
${post.hashtags.join(" ")}

COMMENT PROMPT
--------------
${post.commentPrompt}

SOURCES
-------
${post.sources.map((s) => `• ${s}`).join("\n") || "(see research notes)"}
`;
  fs.mkdirSync(path.join(dir, "out"), { recursive: true });
  fs.writeFileSync(path.join(dir, "out", "post.txt"), txt);
  fs.writeFileSync(path.join(dir, "out", "post.json"), JSON.stringify(post, null, 2));
  log(`post copy → ${path.join(dir, "out", "post.txt")}`);
  return post;
};
